from pathlib import Path
import json
from layout import *
HERE=Path(__file__).resolve().parent
D=json.loads((HERE/'checks.json').read_text())
S3=[(1,2),(2,3),(1,2)];Q=[(1,3),(1,2),(2,3)];S4=[(1,2),(3,4),(1,3),(2,4),(2,3)];N4=[(1,2),(2,3),(3,4),(1,2),(2,3),(1,2)]
pages=[]
pages.append([Paragraph('Sorting machines<br/>Facilitator guide',styles['TitleX']),p('<b>Week 23. Draft and unpiloted. Unscheduled library slot.</b> This guide accompanies the finalized F23-K-v2, F23-23-v2 and F23-45-v2 student packets (6, 6 and 7 pages). It is an adult key, not a lesson already tested with children. Upper pages include small notation examples.'),h('Purpose and quick preparation'),p('Children build a fixed machine, challenge it, and decide what counts as enough evidence. A short counterexample can defeat a machine; certifying every input and proving a minimum require different arguments. The concrete action is compare-exchange, with smaller values going toward lane 1.'),p('<b>For ten children and three adults:</b> prepare three tables. At each table put a reusable four-lane mat at least 24 x 30 cm, eight removable comparator strips plus spares, a marker and blank paper. Supply sixteen cards at least 3 x 3 cm: four distinct ranks, four extra duplicate-value cards, four 0s and four 1s. For nonreaders add four stiff strips of different lengths with a common baseline; numeral/dot versions work too. Total: three mats, at least 24 bars and 48 cards.'),p('Label lanes 1-4 from top to bottom and give every bar exactly two endpoint dots. A long bar may cross another lane without comparing it. Use paper slips or a ruler as a left-to-right time cursor. Do not use the small printed input boxes as card holders: they are recording diagrams, much smaller than the specified cards.'),p('<b>Before children arrive, 10-15 minutes:</b> print the chosen student pages single-sided on Letter at 100%; lay out one mat per table; rehearse input 231 on bars (1,2), (2,3); set aside answer diagrams. Read the applicable key pages. Supply many spare bars so equipment does not announce the optimum. Read directions aloud as needed; do not require reading or writing to participate.'),h('A short shared launch'),p('Give 3 minutes of free handling. Then demonstrate only one bar with cards 3 and 1: both arrive, compare, send 1 above and 3 below. Repeat with already ordered cards and equal cards. Add a third lane; point out that it is untouched. Say: "The bars stay in the same places for every start. Can a start make the machine finish out of order?" Run one two-bar example, then let groups begin. Do not reveal a complete sorter in the launch.'),p('<b>Ground rules:</b> move all cards past the next bar together; never reorder by hand elsewhere, choose the next comparison after looking at values, or reverse a comparator. Ties can stay. Reading, motor speed and ability to copy a diagram are not mathematical gates.')])
pages.append([h('An hour with flexible routes'),table([['Time','Common plan'],['0-8 min','Handle materials, then shared one-bar launch.'],['8-24 min','One substantial opening task; preserve time for failed attempts.'],['24-27 min','Optional movement reset: three volunteers model a single comparator.'],['27-49 min','Continue the same investigation or choose the next ready task.'],['49-57 min','Compare one working machine and one failing start across tables.'],['57-60 min','Photograph a construction, name an open question, and reset materials.']],[72,456]),Spacer(1,10),p('<b>K-1 route:</b> Problems 1-2 are a full core. Offer Problem 3 to compare candidates or Problem 4 when repeated cards are familiar. Problems 5-6 are reserves. A child may demonstrate a failure or make a complete six-start collection orally.'),p('<b>Grades 2-3 route:</b> Problems 1-3 are a repair and minimum route. Problems 4-5 form a separate binary-certification route. Problem 6 introduces a new constraint and a new lower-bound argument; save it until children can track all four cards reliably.'),p('<b>Grades 4-5 route:</b> start with Problems 1-2. Choose either Problems 3-5 (threshold certification) or Problems 6-7 (records and minima). Covering both proof routes in one hour is optional; retain a live question for another meeting.'),h('Prerequisite gates and adult responses'),p('<b>Concrete entry:</b> compare two lengths or dot quantities and track three lanes. The adult moves cards or records starts on request. If children forget a rule, rerun a single bar, then return to their own machine. Offer a pointer, larger cards, tactile lane edges and spoken lane names; use position and labels, not color alone.'),p('<b>Case-coverage gate:</b> distinguish a starting arrangement from its final order; arrange six starts without omissions. A photographed set of six physical starts is as valid as a written list. For binary work, sort test cards by number of 1s, only if organization has become a genuine obstacle.'),p('<b>Proof gates:</b> thresholds need comparison with a chosen number, including negative numbers and equality. History counting needs two choices per bar and reversible token moves. Inversion counting needs relative order of pairs, not multiplication fluency. If those gates are absent, keep the full adult argument available without making it a child performance requirement.'),p('<b>Hold hints:</b> first ask what the child has tried and wait. Then offer the first hint in the key. Give the second only after another attempt. A counterexample is a complete disproof, but many successes are not automatically a universal proof. A successful construction is not automatically minimal.'),p('<b>Common confusions:</b> "lower-numbered" means higher on the page; a crossed lane without an endpoint dot is untouched; five bars are five comparisons even if disjoint bars share a stage. A different bar order can change the machine. Accept any valid construction with a complete justification, not only the pictured one.')])
pages.append([h('Adult reference  Working machines and guarantees'),net(3,S3,'S3  Three bars: (1,2), (2,3), (1,2)',height=95),p('<b>Why S3 works for all values.</b> The first bar orders lanes 1 and 2. The next sends the largest of all three to lane 3. The last orders the two remaining values. This includes ties. The alternative Q = (1,3), (1,2), (2,3) works too: its first two bars put the minimum in lane 1, and the last orders lanes 2 and 3.'),net(4,S4,'S4  Five bars: (1,2), (3,4), (1,3), (2,4), (2,3)',height=122),p('<b>Why S4 works.</b> After the first two bars write the values as a,b,c,d with a &lt;= b and c &lt;= d. Comparing a with c puts the global minimum in lane 1. Comparing b with d puts the global maximum in lane 4. The last bar orders the two middle values. Neither cross-lane bar touches the other pair of endpoints.'),net(4,N4,'N4  Neighbor-only: (1,2), (2,3), (3,4), (1,2), (2,3), (1,2)',height=122),p('<b>Why N4 works and why six is optimal.</b> The first three comparisons send the maximum to lane 4. The next two send the maximum of the remaining three to lane 3; the last orders lanes 1 and 2. In 4321, all six pairs are reversed. Swapping neighboring cards changes only the relative order of that one pair. To reach 1234, every pair must cross; each bar can swap at most one pair. Therefore at least six bars are required. A no-swap bar removes no reversed pair.'),p('<b>Notation in this key.</b> A string such as 231 gives lane values from top to bottom, never left to right across comparator times. Read (1,3) as a bar whose only endpoints are lanes 1 and 3. The diagrams are adult answer references, not a proposed replacement for discovery.')])
pages.append([h('K-1  Problems 1 to 3'),*problem(1,'Test all six starts','The machine is T = (1,2), (2,3). Circle 123, 132, 213 and 312. Do not circle 231 or 321: both finish 213. The six pictures run in that order across the first row and then the second row. See the complete table below.','First: "Have we tried the starts with 1 at the bottom?" Later: hold the first bar fixed and follow just those two starts.','Comparing three quantities is enough. Adult records are fine. Stop when every pictured start has a tested outcome.'),table([['Start','After T','After S3'],['123','123','123'],['132','123','123'],['213','123','123'],['231','213','123'],['312','123','123'],['321','213','123']],[120,150,150]),Spacer(1,7),*problem(2,'Invent the smallest three-lane sorter','Three bars suffice: use S3 on guide page 3, or Q. Fewer do not: two bars have at most four swap/stay records, while there are six distinct starts. The same record reverses from 123 to only one start (full argument on page 11). Alternatively physically inspect all nine two-bar lists using page 6. Zero- and one-bar machines are included, because padding them with repeated bars cannot spoil an already sorted output.','First: "Which starts still fail on your machine?" Later: try a final bar that repairs 213. Hold back the complete S3 until children have an invention attempt.','Making and testing a three-bar construction is a worthwhile stopping point. The minimum proof may be adult-supported; do not confuse failure to invent a two-bar sorter with proof of impossibility.'),*problem(3,'Challenge two three-bar machines','Upper machine S3 sorts every start, so its failure list is empty. Lower machine (1,2), (1,2), (2,3) fails exactly on 231 and 321, finishing 213. Its second bar does nothing: the same pair is already ordered, so it acts just like T. This accounts for all six starts.','First: "What can happen at the repeated bar?" Later: compare the state just after its first and second bars.','Use physical cards and the six-start list. Accept pointing to a final inverted pair as an explanation; keep the notion of a fixed machine explicit.')])
pages.append([h('K-1  Problems 4 to 6'),*problem(4,'Separate the two repeated-card sets','For the left set 001 use T = (1,2), (2,3). It sends the only 1 to lane 3 from any starting lane. It fails on right-set start 110: 110 -> 110 -> 101. For the right set 011 use R = (2,3), (1,2). It sends the only 0 to lane 1. It fails on left-set start 100: 100 -> 100 -> 010. These meet both parts of each request: always on one set and sometimes not on the other.','First: "Which single card needs to get all the way to one end?" Later: try two bars in the opposite order.','Children need to treat the blank dot card as zero and distinguish one 1 from two 1s. Test each of the three arrangements of each set; equal cards need not be distinguished.'),table([['Machine','All starts it must sort','Counterexample on other set'],['T: (1,2), (2,3)','001, 010, 100 -> 001','110 -> 101'],['R: (2,3), (1,2)','011, 101, 110 -> 011','100 -> 010']],[155,175,198]),Spacer(1,8),*problem(5,'Add the missing last bar','Top: append (1,2) to (1,2), (2,3). Middle: append (2,3) to (2,3), (1,2). Bottom: append (2,3) to (1,3), (1,2). These are the unique successful final bars. In the top machine the maximum is already in lane 3; in the other two the minimum is already in lane 1. Sort the remaining pair. Each failing prefix really leaves that pair reversed on some start, so comparing a different pair does not always repair it.','First: "Which card already ends in the right lane every time?" Later: point to the two lanes still reversed on one failed test.','Read the bottom long bar carefully: lane 2 is not an endpoint. Test all six starts after a repair, not just the example used to invent it.'),*problem(6,'Try four cards','Five bars suffice with S4 on page 3. Its minimum/maximum proof certifies all orders. Four bars cannot suffice: 24 distinct starts would need 24 distinct swap/stay records, but four bars allow at most 16 (page 11). The adult may count the 24 starts as four choices for lane 1, then three, then two, then one.','First: "Can you order two pairs before joining them?" Later: "Where could the smallest and largest cards be?"','This is an optional four-lane extension, not an expected K-1 finish. A correct six-bar neighbor machine is progress; the five-bar optimum and universal lower bound can remain an adult explanation. Do not claim a child discovered or proved them without observing it.')])
pages.append([h('Grades 2-3  Problems 1 and 2'),*problem(1,'Collect every successful start','Top T sorts 123,132,213,312; it fails 231,321 -> 213. Middle R sorts 123,132,213,231; it fails 312,321 -> 132. Bottom Q = (1,3),(1,2),(2,3) sorts all six. The first two bars of Q put the minimum in lane 1; its last bar orders the remaining pair.','First: "How will you know none of the six starts is missing?" Later: fix one card in lane 1 and swap the other two, then change the first card.','A complete physical collection with an adult scribe is enough. The order of successful tests is immaterial.'),*problem(2,'Three bars and a lower bound','S3 or Q gives a three-bar construction. The table below gives a failing input for every possible two-bar machine. There are exactly three allowed lane pairs and three choices for the next bar, giving all nine lists. Thus no two-bar sorter works. Padding a shorter proposed sorter with extra comparators would keep its sorted outputs sorted, so this also excludes zero or one bar. The history argument on page 11 is an alternative.','First: "How many choices are there for one bar?" Later: make three piles of candidate lists, one for each first bar.','Try the tangible nine-list proof before powers of two if needed. Distinguish all two-bar lists from merely removing a bar from one favorite sorter.'),table([['First bar','Second bar','One failing start','Final order']]+[[f'({a},{b})',f'({c},{d})',s,''.join(map(str,__import__('checks').run(tuple(map(int,s)),[(a,b),(c,d)])[0]))] for a,b in [(1,2),(1,3),(2,3)] for c,d in [(1,2),(1,3),(2,3)] for s in [D['two_bar_witnesses'][str(((a,b),(c,d)))]]],[100,100,125,125]),Spacer(1,8),p('<b>Do not hand out the table first.</b> It is an adult certificate and a way to check a child-generated list. One row is a suitable held scaffold when the child wants a systematic impossibility argument.')])
pages.append([h('Grades 2-3  Problems 3 and 4'),*problem(3,'Repair or rule out a one-bar repair','Top: append (2,3), giving S4. Middle: append (2,3) to (1,3),(2,4),(1,2),(3,4). After the first two comparisons, minima of the two original pairs occupy lanes 1,2 and maxima occupy lanes 3,4; the next two put the global minimum in 1 and maximum in 4. The final bar orders the middle. Bottom: impossible. Input 2413 finishes 2143 under (1,2),(3,4),(1,4),(2,3). Both disjoint pairs 2,1 and 4,3 are reversed, and all four positions are wrong. One bar can change only two positions, so cannot produce 1234. This one input defeats every possible appended bar.','First: "What remains wrong just before the blank last bar?" Later: for the bottom, seek a finish with four positions wrong.','A failed attempted repair is not enough for impossibility. The witness 2143 plus the two-position argument is enough. Long bars compare endpoints only.'),*problem(4,'An incomplete binary certificate','All six arrangements of 0011 are 0011,0101,0110,1001,1010,1100. The printed machine W = (1,2),(1,3),(2,3),(2,4) sends each to 0011. It does not sort every binary start. Exactly these fail: 0010,0100,1000 finish 0010; 1110 finishes 1101. The first three have one 1; the last has three 1s. Testing only a fixed number of 1s misses them.','First: "What kinds of starts have we not used at all?" Later: use one 1, then move it through the four lanes.','Children should understand that equal cards create fewer different value arrangements than labeled-card permutations. Stop once the six-start claim and a counterexample to the stronger claim are both clear.'),table([['Number of 1s','All binary starts in this class','W result'],['0','0000','Sorted'],['1','0001, 0010, 0100, 1000','Only 0001 sorts'],['2','0011, 0101, 0110, 1001, 1010, 1100','All sort'],['3','0111, 1011, 1101, 1110','Only 1110 fails'],['4','1111','Sorted']],[88,300,140]),Spacer(1,9),p('<b>Teaching choice.</b> Let children find a counterexample before supplying this class-by-class audit. The distinction is substantive: a full certificate needs every binary input, not many trials of the one pictured multiset.')])
pages.append([h('Grades 2-3  Problems 5 and 6'),*problem(5,'Build and certify a binary sorter','Use S4 (five bars) or N4 (six neighbor-only bars), both on page 3. The complete S4 audit below checks all 16 starts once; there are 2 choices in each of 4 lanes. Each output has the same number of 1s as its input and is ordered. Problem 5 asks for a full record, not an optimum. A different successful fixed construction is valid.','First: "How could you group starts so a missing one is visible?" Later: arrange by number of 1s, or choose the first bit and list every three-bit ending.','Keep the audit manageable with photographs, stamps or adult transcription. Repeated random starts cannot establish completeness.'),table([['Start','Output','Start','Output']]+[[''.join(map(str,D['four_binary_audit'][i]['input'])),''.join(map(str,D['four_binary_audit'][i]['output'])),''.join(map(str,D['four_binary_audit'][i+8]['input'])),''.join(map(str,D['four_binary_audit'][i+8]['output']))] for i in range(8)],[95,125,95,125]),Spacer(1,8),*problem(6,'The neighbor-only optimum','Exactly six bars. N4 gives the construction and the proof on page 3. For a lower bound start 4321: the six reversed pairs are 4/3,4/2,4/1,3/2,3/1,2/1. To sort, each pair must reverse relative order. A neighboring swap crosses only one pair; it cannot change any other pair\'s relative order. Thus at least six swaps, and at least six bars, are needed. This is stronger than the unrestricted five-bar lower bound because the neighbor restriction matters.','First: "What must happen to each pair in 4321?" Later: place a mark for each reversed pair and see how many disappear in one adjacent swap.','Require neighboring endpoints on every bar. Trace pairs with labeled strips if inversion counting is unfamiliar. A valid six-bar sorter plus this pair-crossing explanation completes the task.'),p('<b>Reverse-input trace for N4:</b> 4321 -> 3421 -> 3241 -> 3214 -> 2314 -> 2134 -> 1234. Every bar swaps on this input. Independently checked: all 24 distinct starts and all 16 binary starts pass N4; none of the 243 length-five neighbor-only lists sorts all distinct starts.')])
pages.append([h('Grades 4-5  Problems 1 to 3'),*problem(1,'Distinct and repeated values','Upper machine T fails exactly on 231 and 321 among distinct ranks; both finish 213. It sorts 113,131,311, all to 113. For 133 it sorts 133 and 313, but 331 finishes 313. Lower machine Q sorts every one of these inputs by the minimum-then-last-pair argument on page 3. Distinct-rank tests alone are not a written explanation of repeated-value behavior unless an order-preserving argument is supplied.','First: "Which distinct-rank failure might survive when two cards become equal?" Later: compare 231 with 331 and with 311.','Track equal values without pretending identical cards yield different value arrangements. A small explicit test list is valid here.'),*problem(2,'Construct a four-lane sorter','S4 uses five bars and its general proof is on page 3. The exact minimum is five, by the 24-input versus 16-history lower bound on page 11. If a child finds N4 first, keep it as a correct six-bar machine and look for a shorter one; do not imply the local neighbor-only bound applies when long bars are allowed.','First: "Can you first sort two pairs?" Later: "Can the smallest and largest be settled before the middle pair?"','The proof of optimality can wait until Problem 7. Preserve a photograph of each original construction before editing.'),sub('Problem 3  Every threshold row'),p('<b>Solution.</b> The rows and exact threshold ranges are below. With the rule value &lt;= t gives 0, equality belongs to the interval on its right. Equal values cross the threshold together.'),table([['Start','Threshold range','Bit row'],['(-2,8,5,8)','t &lt; -2; -2 &lt;= t &lt; 5; 5 &lt;= t &lt; 8; t &gt;= 8','1111; 0111; 0101; 0000'],['(6,2,9,4)','t &lt; 2; 2 &lt;= t &lt; 4; 4 &lt;= t &lt; 6;<br/>6 &lt;= t &lt; 9; t &gt;= 9','1111; 1011; 1010;<br/>0010; 0000'],['(4,4,4,4)','t &lt; 4; t &gt;= 4','1111; 0000']],[112,263,153]),Spacer(1,7),p('<b>Commutation argument.</b> For two values, either both are at most t (both bits 0), both exceed t (both 1), or one lies on each side (comparison gives 0 above 1). These exhaust the cases. Comparing numbers then replacing them therefore gives the same bits as replacing first and comparing the bits.'),p('<b>Hold hints.</b> First: move t along a number line. Later: only passing one of the displayed distinct values can change a bit. <b>Gate:</b> read negative numbers and inclusive inequality; offer a number line and oral description. Stop when all rows and the three-case comparator argument are accounted for.')])
pages.append([h('Grades 4-5  Problems 4 and 5'),*problem(4,'Why binary tests cover all numbers','No. Choose any t with 4 &lt;= t &lt; 9, for example t=4. Thresholding the alleged output makes lane 2 a 1 and lane 3 a 0. By Problem 3, thresholding commutes with every comparator, hence with the complete fixed list, one bar at a time. The thresholded input is a binary start that would end unsorted, contradicting the premise. More generally, any unsorted numerical output has an earlier value x larger than a later y. Choose t=y. The same argument yields an earlier 1 and later 0. Therefore sorting every binary input guarantees sorting every numerical input, including repeated values.','First: "Choose a threshold separating 4 and 9." Later: compare the two routes through one bar before extending to the whole machine.','The key gate is the one-bar commuting argument, not symbolic proof language. Children may draw two paths that meet at the same bit output. The network must remain fixed for this reasoning.'),*problem(5,'Which five-bar machine really sorts','Upper is S4 and sorts all numerical inputs. One complete justification is its 16-row audit on page 8 combined with Problem 4; another is the minimum/maximum proof on page 3. Lower has bars (1,2),(3,4),(1,3),(2,3),(2,4). It fails on binary inputs 0100 and 1000, both ending 0010. Thus it cannot sort every numerical input; a single binary counterexample suffices, including a repeated-value input. All its other binary starts sort.','First: "Does moving the middle comparison earlier leave a new problem later?" Later: try a single 1 in lane 1 or lane 2.','Do not treat identical bar sets as identical networks: their order matters. After finding a failure, stop testing the failed candidate if the requested decision is already settled.'),net(4,[(1,2),(3,4),(1,3),(2,3),(2,4)],'Lower printed candidate  Same pairs, harmful order',height=120),p('<b>Explicit failing trace:</b> 1000 -> 0100 -> 0100 -> 0100 -> 0010 -> 0010. The fourth bar moves the 1 to lane 3, and the last bar never touches lane 3. This is a useful way to check a child\'s counterexample without giving the answer in advance.'),h('A worthwhile stopping point'),p('A group that understands why sixteen deliberate tests certify infinitely many numerical inputs has completed a substantial proof investigation. It need not also finish the optimality route. Invite a child to explain what a threshold does with a new repeated-value example, then preserve the unfinished minimum question for later.')])
pages.append([h('Grades 4-5  Problems 6 and 7'),sub('Problem 6  All swap and stay records'),p('<b>Solution.</b> Read S as a swap and N as no swap, from left to right. These are every record and every start producing it; the six permutations exhaust the input set.'),table([['Machine','Record','All starts','Final order(s)'],['T: (1,2),(2,3)','NN','123','123'],['T','NS','132, 231','123, 213'],['T','SN','213','123'],['T','SS','312, 321','123, 213'],['S3: (1,2),(2,3),(1,2)','NNN','123','123'],['S3','NSN','132','123'],['S3','SNN','213','123'],['S3','NSS','231','123'],['S3','SSN','312','123'],['S3','SSS','321','123']],[182,65,120,125]),Spacer(1,7),p('<b>Why two different starts cannot both sort with the same record.</b> Fix the lane pairs and record. Every S swaps a specified pair of positions and every N leaves them alone; together these are one fixed, reversible permutation of tokens. Starting at sorted 123 and undoing this record in reverse order recovers one unique start. Two starts can share a record, as T shows, but at most one finishes sorted.'),p('<b>Hold hints.</b> First: group trials by their S/N string. Later: run one record backward from 123. <b>Gate:</b> distinct cards and reversible swaps; do not apply this count to indistinguishable repeated-value arrangements.'),sub('Problem 7  Exact unrestricted minima'),p('<b>Solution.</b> Three lanes need exactly 3 bars; four lanes need exactly 5. S3 and S4 attain them (page 3). A k-bar network has at most 2<super>k</super> records, because each bar contributes S or N. Some strings may never occur, which only lowers the count. Every distinct input order needs its own successful record by Problem 6. For three cards, 3 x 2 x 1 = 6 starts exceed 2<super>2</super> = 4 records. For four cards, 4 x 3 x 2 x 1 = 24 starts exceed 2<super>4</super> = 16 records. Therefore two or four bars respectively cannot work, and neither can shorter lists.'),p('<b>Hold hints.</b> First: compare the count of starts with possible records. Later: build the two-choice record tree for two bars and extend it. <b>Gate:</b> counts of choices and the one-record argument must both be understood. Merely naming 6 &gt; 4 and 24 &gt; 16 leaves the crucial connection unstated. Count bars, not parallel stages.')])
pages.append([h('Extensions and responsible reuse'),p('<b>Depth extension, after a successful sorter.</b> Which bars can run together? S4 has the three stages {(1,2),(3,4)}, {(1,3),(2,4)}, {(2,3)}. A lane cannot take part in two simultaneous comparisons. Three stages are optimal on four lanes: at most two disjoint bars fit in one stage on four lanes, so two stages contain at most four bars, fewer than the five-bar lower bound. Keep this as a separate question from bar count.'),p('<b>Neighbor extension.</b> For n distinct cards in reverse order, all n(n-1)/2 pairs must cross using adjacent swaps. The fixed repeated left-to-right pass construction uses exactly (n-1)+(n-2)+...+1 bars and sorts by fixing the largest remaining card at each pass. Thus the neighbor-only optimum is n(n-1)/2. Invite children to establish n=5 before generalizing.'),p('<b>Order-preserving relabeling.</b> Replace 1,2,3,4 by 10,20,30,40 or four increasing lengths. Every comparison decision is unchanged. Ask what fails if the relabeling reverses just two ranks. This develops the threshold idea without requiring negative numbers.'),h('Sources and evidence limits'),p('<b>Final student authority:</b> final/k-1.pdf, final/grades-2-3.pdf and final/grades-4-5.pdf, with their final/src/build_packets.py, F23 v2. The local PROMPT.md, review.md and review-math.md were consulted. Reviews describe an earlier draft: the final K-1 Problem 4, middle Problem 6 and upper Problem 6 were freshly checked here, not inferred from those reviews.',True),p('<b>Mathematical source:</b> University of Liverpool, COMP308, Lecture 17, "Sorting networks," PDF pp. 1-2, comparator definition and zero-one principle. Verified 2026-10-03: <link href="https://cgi.csc.liv.ac.uk/~igor/COMP308/files/Lecture17.pdf" color="#155676">cgi.csc.liv.ac.uk/~igor/COMP308/files/Lecture17.pdf</link>. The exact small constructions, repairs, histories and minima in this guide are independently derived and exhaustively checked; the lecture is not being cited as their classroom test.',True),p('<b>Teaching source:</b> Laura Givental, Maria Nemirovskaya and Ilya Zakharevich, <i>Math Circle by the Bay</i>, preface printed pp. viii-x (local PDF pp. 9-11): substantial themes across levels, manipulatives and dialogue, clear accessible tasks, and adaptable depth and pace. Read directly. Our minute menu, particular hints and readiness gates are proposed applications, not claims tested in that book or with this group.',True),p('<b>Local evidence:</b> README.md and plans/week-01-classroom-review.md record the organizer\'s need for a shared concrete launch, enough independent work, and representations introduced when useful. Those observations concern earlier activities. They support the format choice, not an assertion that sorting networks will engage every child.',True),h('Verification and after-session notes'),p('checks.py independently enumerates all 6 and 24 distinct starts, all 16 four-bit starts, all 9 two-bar three-lane lists, all 1,296 four-bar unrestricted lists and all 243 five-bar neighbor lists. It validates repair uniqueness and the exact histories. checks.json preserves results. The human arguments above explain why the claims hold; exhaustive checks are an additional error detector.',True),p('Record which problems and examples were actually attempted, which rules needed repair, which arguments children supplied, and where a hint changed the activity. Distinguish observations from guesses about causes. Do not turn this prepared guide into a claim of classroom success or schedule it merely because it is numbered Week 23.',True)])
build(pages,HERE.parent/'build'/'facilitator-guide.pdf',23,'Sorting machines')
print(f'Built {len(pages)} planned pages')
